    const root = rootCallName(node.callee);
    if (root !== "it" && root !== "test") {
        return false;
    }
    const first = node.arguments[0];
    if (!first) {
        return false;
    }
    if (first.type === "Literal") {
        return typeof first.value === "string";
    }
    return first.type === "TemplateLiteral";
